  const n = s.run(); const st = r.stats();
  console.log(`   Wq sim ${st.meanWait.toFixed(3)} vs Erlang C ${erlangCWait(lam, mu, c).toFixed(3)}; util ${st.utilization.toFixed(3)} vs ${(lam / mu / c).toFixed(3)}`);
