// listed in README.md "Decisions".

const STRENGTHS = ['shall', 'should', 'may'];
const METHODS = ['test', 'analysis', 'inspection', 'demonstration'];
const ID_RE = /^[A-Z][A-Z0-9]*(-[A-Z0-9]+)*$/;

