// "at <= asOf" compared as days; asOf undefined/null means everything counts.
const onOrBefore = (at, asOf) => asOf == null || dayNumber(at) <= dayNumber(asOf);

// ---------- M1 ----------
function childrenMap(reqs) {
  const m = new Map();
  for (const r of reqs) if (hasParent(r)) {
